INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65409345', 65409345, 'analyze_legacy', 'Kab. Rokan Hulu', 'kabkota', 'Dinas Kesehatan', 'Belanja Bahan Alat Rumah Tangga Kantor ( BHP Rumah Tangga dan BHP Peralatan Rumah Tangga)', 'Barang', 'Penunjukan Langsung', 'Riau, Rokan Hulu (Kab.)', 600000000, 'January 2026', 'BLUD', 1, 1, '1 Paket', '"Belanja kebutuhan rutin rumah tangga kantor (kebersihan dan kelistrikan ringan) untuk operasional gedung dan pelayanan RSUD Rokan Hulu selama 1 Tahun Anggaran.', 'Penyedia wajib menawarkan produk dengan ketentuan: 1. Izin Edar Kemenkes (PKRT): Seluruh bahan kimia pembersih (Sabun, Disinfektan, Pewangi) wajib memiliki Nomor Izin Edar PKD (Perbekalan Kesehatan Rumah Tangga) dari Kemenkes RI yang masih berlaku. 2. Standar SNI: Seluruh peralatan listrik (Lampu, Kabel, Saklar) wajib berlabel SNI (Standar Nasional Indonesia) yang terembos pada fisik barang. 3. Tingkat Komponen Dalam Negeri (TKDN): Memprioritaskan produk dengan nilai TKDN + BMP minimal 40% sesuai etalase E-Katalog. 4. Keamanan Bahan (MSDS): Menyertakan Material Safety Data Sheet (MSDS) untuk bahan kimia pembersih (jika diminta).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2140504);
