INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65451632', 65451632, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'PENGEMBANGAN KENAVIGASIAN PUSAT', 'Training  General Operator Radio Sertificate (GOC) GMDSS', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 1163630000, 'March 2026', 'APBN - PNBP (D)', 1, 1, '1 PAKET', 'Sesuai dengan Peraturan Menteri Perhubungan Nomor PM 4 tahun 2023 Tentang Penyelenggaraan Telekomunikasi-Pelayaran Dan Pelayanan Tata Kelola Lalu Lintas Kapal Di Perairan Indonesia telah diatur terkait dengan standar kompetensi operator radio untuk Stasiun Radio Pantai (SROP) dan Vessel Traffic Services (VTS) untuk memperoleh sertifikat Kompetensi Operator Radio. Direktorat Kenavigasian saat ini mempunyai Stasiun Radio Pantai (SROP) sebanyak 158 lokasi diantaranya sebanyak 114 SROP telah dilengkapi sistem Global Maritime Distress Safey System (GMDSS) yang bertugas dalam memberikan layanan komunikasi dan jaga dengar marabahaya pelayaran dan juga menyelenggarakan 23 (Dua Puluh Tiga) Vessel Traffic Servives (VTS) untuk mendukung fungsi Keselamatan Pelayaran.', 'Kategori Sertifikasi Radio Elektronika Dan Operator Radio (REOR) adalah kompetensi yang harus dimiliki oleh operator Telekomunikasi Pelayaran dalam menjalankan operasional layanan Kenavigaisan, kompetensi tersebut adalah sebagai berikut : a. Sertifikat Operator Radio Elektronika Kelas I, Sertifikat ini dikeluarkan menurut artikel 47 Peraturan Radio edisi tahun 2001 dan Konvensi Internasional IV/2 SCTW 1978, yang telah dirubah tahun 1995 dan tahun 2010, dan sesuai rekomendasi Organisasi Maritim Internasional untuk pelatihan Personal Radio dan Sistem Marabahaya dan Keselamatan Global. Pemilik Sertifikat Radio Elektronika Kelas I berwenang melakukan pemeliharaan dan perbaikan perangkat dan atau menyelenggarakan Dinas Telepon Radio pada Stasiun Radio Kapal dan Stasiun Radio Bumi Kapal dalam wilayah/area A1, A2, A3, dan A4 GMDSS. b. Sertifikat Operator Radio Elektronika Kelas II, Sertifikat ini dikeluarkan menurut artikel 47 Peraturan Radio edisi tahun 2001 dan Konvensi Internasional IV/2 STCW 1978, yang telah dirubah tahun 1995 dan tahun 2010, dan tahun 2010 dan sesuai rekomendasi Organisasi Maritim Internasional (IMO) untuk pelatihan Personal Radio dalam Sistem Marabahaya dan Keselamatan Global. Pemegang sertifikat Radio Elektronika Kelas II berwenang melakukan pemeliharaan perangkat dan atau menyelenggarakan Dinas Telepon Radio pada Stasiun Radio Kapal dan Stasiun Bumi Kapal dalam wilayah/area A1, A2, A3, dan A4 GMDSS. Masa berlakunya Sertifikasi Radio Elektronika Dan Operator Radio (REOR) untuk Sertifikasi Operator Radio berlaku selama 5 tahun dan dapat diperpanjang. c. Sertifikat Operator Umum, Sertifikat ini dikeluarkan menurut artikel 47 Peraturan Radio edisi tahun 2001 dan Konvensi Internasional IV/2 STCW 1978, yang telah dirubah tahun 1995 dan tahun 2010, dan sesuai rekomendasi Organisasi Maritim Internasional (IMO) untuk pelatihan Personal Radio dalam Sistem Marabahaya dan Keselamatan Global. Pemegang sertifikat ini berwenang untuk melakukan pekerjaan operator radio di kapal yang berlayar di area A1, A2, A3, A4 yang dilengkapi dengan perangkat GMDSS dan Operator Radio Pantai. d. Sertifikat Operator Terbatas, Sertifikat ini dikeluarkan menurut artikel 47 Peraturan Radio edisi tahun 2001 dan Konvensi Internasional IV/2 SCTW 1978, yang telah dirubah tahun 1995 dan tahun 2010, dan sesuai rekomendasi Organisasi Maritim Internasional untuk pelatihan Personal Radio dalam sistem Marabahaya dan Keselamatan Global. Pemegang sertifikat ini berwenang untuk melakukan pekerjaan operator radio di kapal yang berlayar di area A1, yang dilengkapi dengan perangkat GMDSS. Operator SROP dan VTS Direktorat Jenderal Perhubungan Laut sampai dengan saat ini masih memiliki kekurangan operator serta dengan kondisi saat ini masih memerlukan pemenuhan kecukupan kompetensi. Sebagai Sertifikat Dasar, Sertifikasi Operator Radio Umum (ORU) diperlukan untuk kewajiban mutlak operator telekomunikasi pelayaran sesuai aturan Nasional dan Internasional untuk melakukan pekerjaan operator di area A1, A2, A3, A4 yang dilengkapi dengan perangkat GMDSS serta Operator Radio Pantai.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2141938);
