INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65450812', 65450812, 'analyze_legacy', 'Kab. Pidie', 'kabkota', 'DINAS PENDIDIKAN DAN KEBUDAYAAN', 'Pengadaan APE PAUD (DAU SG)', 'Barang', 'E-Purchasing', 'Aceh, Pidie (Kab.)', 118192060, 'March 2026', 'APBD', 1, 1, '1 Paket', 'BES ALAT MERONCE PAUD; BES KARTU HURUF DAN ANGKA PAUD; BES MAINAN PUKUL PALU PAUD; BES PUZZLE PAUD; BES REPLIKA HURUF DAN ANGKA PAUD; BES TIMBANGAN PAUD; Bola PAUD Berbagai Ukuran; Boneka Gender PAUD; Set Alat Musik PAUD; WIRE GAME PAUD 3 JALUR;', 'Spesifikasi: Manik berbahan kayu - Syarat bahan kayu : tidak berjamur, tidak berlubang jarum atau titik-titik hitam dan kayu tidak bermata - Diameter manikmanik 2cm dan 2,5cm - Diameter lubang 0,8cm - Terdapat 3 warna primer Terdiri dari 5 bentuk manik geometri (setiap bentuk 10 buah) - Dikemas dalam box tertutup (tidak bercampur antar bentuk ) yang sesuai dengan isi (proposional) dan setiap bentuk tidak tercampur - Dilengkapi dengan 5 buah tali warna warni, ukuran panjang 40cm, diameter 0,3cm. Ujung tali diberi Penguat supaya tidak terurai - Dilengkapi dengan petunjuk penggunaan; Terbuat dari Bahan Kayu; Bahan kayu solid - Ukuran panjang 20cm x lebar 15cm x tinggi 10cm - Warna papan natural, pasak warna warni - Terdiri dari minimal 5 pasak dengan empat warna berbeda dan satu palu - Ukuran pasak disesuaikan dengan ukuran papan secara proporsional - Lubang pasak tidak longgar dan tidak sempit - Kayu tidak berjamur - Kayu tidak berlubang jarum/titik-titik hitam - Kayu tidak bermata - Dikemas rapi dan kuat - Dilengkapi dengan petunjuk penggunaan produk; Terbuat dari bahan kayu (MDF); • Ukuran minimal kepingan ± panjang 5 cm x lebar 5 cm, tebal minimal 0.5 cm; • Ukuran bingkai puzzle ± panjang 25cm x lebar 20cm; • Gambar puzzle sesuai dengan salah satu tema pada pembelajaran/ agama/ budi pekerti; • Warna menyesuaikan gambar/ sesuai konteks dengan bentuk dan ukuran gambar proporsional sesuai dengan kehidupan nyata; • Dicetak mendekati gambar asli (digital printing/sablon); • Puzzle terdiri dari: 6 keping, 9 keping, dan 12 keping; Bahan dari kayu dengan dimensi rata-rata kurang lebih 3cm-5cm. Minimal memuat huruf kecil a-z dan angka 0-9. Berwarna dengan pewarna non toxic dan menarik perhatian anak; Terbuat dari bahan kayu; • Dimensi umum timbangan ukuran minimal p x l x t = 23 cm x 11 cm x 15 cm; • Masing-masing anak timbangan berisi beban berbentuk geometri; • Beban dan ukuran pada setiap sisi menunjukkan presisi keseimbangan; Spesifikasi Produk: • Bahan berbahan plastik dilengkapi lubang pentil • Bola dapat memantul • Memuat salah satu warna primer dan polos • Jumlah 1 set memuat bola kecil, bola sedang dan bola besar • Bola kecil: berdiameter 8 cm • Bola sedang : berdiameter 18 cm • Bola besar : diameter 22 cm, • Dilengkapi dengan petunjuk penggunaan produk Jenis Alat: APE PAUD Indoor Fungsi: Untuk menstimulasi perkembangan fisik- motorik (motorik kasar dan halus) dan kognitif (berpikir logis). Negara Asal Produk: Indonesia Memiliki SVLK (Label Ramah Lingkungan Untuk Kayu): Tidak Label Ramah Lingkungan Hidup (Non Kayu): Tidak Ketersediaan Suku Cadang: YA SNI: YA Garansi Produk: 1 Bulan Keterangan Lainnya: • Bahan berbahan plastik dilengkapi lubang pentil • Bola dapat memantul • Memuat salah satu warna primer dan polos • Jumlah 1 set memuat bola kecil, bola sedang dan bola besar • Bola kecil: berdiameter 8 cm • Bola sedang : berdiameter 18 cm • Bola besar : diameter 22 cm, • Dilengkapi dengan petunjuk penggunaan produk; Bahan plastik • Setiap 1 set memuat 1 boneka laki-laki dan 1 perempuan, lengkap dengan pakaian gender masing-masing • Ukuran 30 cm x 15 cm • Warna tropis/ warna kulit orang Indonesia; Bahan plastik/ kayu atau logam, Jumlah 1 set memuat 4 buah, Memiliki warna yang menarik perhatian anak, . jenis alat musik : xylophone,rebana, gendang, marakas, kencreng, Jika bahan kayu maka kayu tidak berjamur, tidak berlubang atau titik-titik hitam, tidak bermata.; Bahan kayu dan kawat - Ukuran papan panjang 20cm x lebar 25cm x tinggi 30cm - Terdapat minimal tiga alur kawat beda warna - Masingmasing berisi biji minimal warna primer -Warna papan natural, buah warnawarni - Warna menggunakan cat nontoxic - Kemasan rapi dan kuat Dilengkapi dengan petunjuk penggunaan produk;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2142149);
