INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65454103', 65454103, 'analyze_legacy', 'Provinsi DI Yogyakarta', 'provinsi', 'DINAS PEMBERDAYAAN MASYARAKAT, KALURAHAN, KEPENDUDUKAN DAN PENCATATAN SIPIL', 'Belanja Jasa Konsultansi Berorientasi Bidang-Telematika (content creator)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 42000000, 'February 2026', 'APBD', 1, 1, '10 bulan', 'Dinas Pemberdayaan Masyarakat Kalurahan Kependudukan dan Pencatatan Sipil DIY secara konsisten melaksanakan berbagai kegiatan penguatan tata kelola dan pemberdayaan masyarakat. Misalnya melalui forum monitoring dan evaluasi BKK, pembaruan dan pemutakhiran data kalurahan, penguatan kelembagaan Posyandu. Dinas Pemberdayaan Masyarakat Kalurahan Kependudukan dan Pencatatan Sipil DIY juga bisa menfasilitasi ruang dialog antara pemerintah dan masyarakat kalurahan. Ragam aktivitas tersebut menghasilkan informasi, data, praktik baik, dan capaian program yang perlu dikomunikasikan secara sistematis, menarik, dan berkelanjutan kepada publik. Dalam konteks tersebut, media sosial menjadi kanal strategis komunikasi publik pemerintah yang mampu menjangkau masyarakat secara luas, cepat, dan interaktif. Pengelolaan konten media sosial yang profesional, terencana, dan berbasis substansi kebijakan menjadi kebutuhan penting untuk memastikan kinerja Dinas PMK Dukcapil DIY tersampaikan secara akurat, transparan, dan mudah dipahami oleh masyarakat.', 'Tenaga Ahli Konten Kreator yang memiliki kemampuan dalam mengemas informasi kebijakan, program, dan kegiatan Dinas Pemberdayaan Masyarakat Kalurahan Kependudukan dan Pencatatan Sipil DIY. Kegiatan yang dilakukan perlu di kemas dalam konten komunikasi publik yang edukatif, informatif, dan partisipatif. Kehadiran pengelola konten ini diharapkan mampu memperkuat citra kelembagaan, meningkatkan literasi publik terhadap Reformasi Kalurahan, serta mendorong keterlibatan aktif masyarakat dalam pembangunan kalurahan berbasis keistimewaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2142829);
