INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65455071', 65455071, 'analyze_legacy', 'Provinsi DI Yogyakarta', 'provinsi', 'DINAS PEMBERDAYAAN MASYARAKAT, KALURAHAN, KEPENDUDUKAN DAN PENCATATAN SIPIL', 'Belanja Jasa Konsultansi Berorientasi Layanan-Jasa Khusus (Pendamping Penerapan Reformasi Birokrasi Kalurahan)', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 42000000, 'February 2026', 'APBD', 1, 1, '10 bulan', 'Reformasi Kalurahan merupakan kebijakan strategis Pemerintah Daerah Daerah Istimewa Yogyakarta. Kebijkan ini berakar pada spirit pembaruan tata kelola pemerintahan kalurahan pada masa Sri Sultan Hamengku Buwono IX. Beliau menekankan prinsip kemandirian, efisiensi, dan keberdayaan masyarakat. Dalam perkembangannya, Reformasi Kalurahan tidak lagi dimaknai sebatas penataan wilayah atau struktur kelembagaan, melainkan diarahkan pada penguatan tata kelola pemerintahan kalurahan yang transparan dan akuntabel. Selain itu, peningkatan kualitas pelayanan publik, pengelolaan keuangan yang bertanggung jawab, serta pemberdayaan masyarakat secara berkelanjutan. Pelaksanaan Reformasi Kalurahan di DIY dilaksanakan melalui dua pilar utama. Pertama, Reformasi Birokrasi Kalurahan. Kedua, Reformasi Pemberdayaan Masyarakat. Hal ini diterapkan secara masif pada seluruh kalurahan. Implementasi kedua pilar tersebut memerlukan dukungan komunikasi publik yang efektif. Dinas Pemberdayaan Masyarakat Kalurahan, Kependudukan, dan Pencatatan Sipil Daerah Istimewa Yogyakarta memiliki peran strategis dalam hal ini. Dinas Pemberdayaan Masyarakat Kalurahan Kependudukan dan Pencatatan SIpil DIY merupakan perangkat daerah yang bertanggung jawab dalam pembinaan penyelenggaraan pemerintahan kalurahan, penguatan kapasitas kelembagaan masyarakat, serta penjaminan tertib administrasi kependudukan dan pencatatan sipil. Peran tersebut dijalankan sesuai dengan ketentuan Surat Keputusan Gubernur Daerah Istimewa Yogyakarta tentang pembentukan, kedudukan, susunan organisasi, tugas, dan fungsi perangkat daerah.', 'a. Memberikan masukan, saran, ide / gagasan dan telaah baik secara lisan dan tertulis tentang Penerapan Reformasi Kalurahan b. Mendampingi dalam Focus Group Discusion (FGD), diskusi, rapat koordinasi maupun komunikasi dengan pengampu kepentingan dalam rangka Penerapan Reformasi Kalurahan; c. Menyusun Laporan Penerapan Reformasi Pemberdayaan Masyarakat Kalurahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2148419);
